create table if not exists automation_jobs(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenants(id) on delete cascade,user_id uuid references users(id) on delete cascade,channel_id uuid references channels(id) on delete cascade,project_id uuid references projects(id) on delete cascade,parent_job_id uuid references automation_jobs(id),job_type text not null,status text not null default 'queued',progress_percent numeric(5,2) not null default 0,current_step text,current_item text,total_items int default 0,completed_items int default 0,failed_items int default 0,worker_id text,provider text,model text,priority int not null default 4,checkpoint jsonb not null default '{}',idempotency_key text unique,retry_count int not null default 0,max_retries int not null default 3,error_code text,error_message text,input jsonb not null default '{}',output jsonb not null default '{}',lease_until timestamptz,next_attempt_at timestamptz,started_at timestamptz,updated_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now());
